H, W, K = map(int, input().split())
S = [list(input()) for _ in range(H)]

min_operations = float('inf')

# Check each row
for s in S:
    p = 0
    for i in range(W):
        if i < K:
            if s[i] == '.':
                p += 1
        else:
            if s[i] == '.':
                p += 1
            if s[i - K] == '.':
                p -= 1
        if i >= K - 1:
            min_operations = min(min_operations, p)

# Transpose the grid and check each column
S_t = [list(x) for x in zip(*S)]

for s in S_t:
    p = 0
    for i in range(H):
        if i < K:
            if s[i] == '.':
                p += 1
        else:
            if s[i] == '.':
                p += 1
            if s[i - K] == '.':
                p -= 1
        if i >= K - 1:
            min_operations = min(min_operations, p)

print(min_operations if min_operations != float('inf') else -1)
